// VELMARA poster entry: hand in the committed poster as /output/entry.png.
// The poster itself is generated by build_poster.py (see README); this
// program simply delivers the finished artifact to the grader's output
// directory, with no network and no dependencies beyond Node itself.
import { copyFileSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, "poster.png");
const outputDir = "/output";
const target = join(outputDir, "entry.png");

mkdirSync(outputDir, { recursive: true });
copyFileSync(source, target);

// Sanity check the hand-in: the gate caps the artifact at 1 MiB, so fail
// loudly here rather than hand in an oversize file in silence.
const bytes = statSync(target).size;
if (bytes > 1_048_576) {
  throw new Error(`entry.png is ${bytes} bytes, over the 1048576 byte cap`);
}
console.log(`wrote ${target} (${bytes} bytes)`);
